def rellenar_periodo_clave(apps, schema_editor):
    """Calcula `periodo_clave` de los cierres ya declarados.

    El campo lo mantiene `CierreUnidad.save()`, pero las filas anteriores a esta
    migración nunca pasaron por ahí: sin este relleno quedarían con la clave
    vacía y no aparecerían en el desplegable de períodos del Informe Inteligente.
    """
    CierreUnidad = apps.get_model('cierres', 'CierreUnidad')
    for cierre in CierreUnidad.objects.filter(periodo_clave='').only('id', 'anno', 'mes'):
        CierreUnidad.objects.filter(pk=cierre.pk).update(
            periodo_clave=f'{cierre.anno}-{cierre.mes:02d}')


