def enlazar_aspirante_vivo(apps, schema_editor):
    """Enlaza las fotografías ya tomadas con la persona viva correspondiente.

    `aspirante_id_original` ya guarda ese pk desde el principio, así que el
    enlace se puede reconstruir sin pérdida. Se salta a quien ya no exista: la
    FK es SET_NULL justamente para ese caso.
    """
    CierreContrato = apps.get_model('cierres', 'CierreContrato')
    Aspirante = apps.get_model('bolsa', 'Aspirante')

    existentes = set(Aspirante.objects.values_list('pk', flat=True))
    for fila in CierreContrato.objects.filter(
            aspirante_vivo__isnull=True, aspirante_id_original__isnull=False
    ).only('id', 'aspirante_id_original'):
        if fila.aspirante_id_original in existentes:
            CierreContrato.objects.filter(pk=fila.pk).update(
                aspirante_vivo_id=fila.aspirante_id_original)


